 static int detect_method(const u8* in, size_t inLen) {
        if(inLen > 2 && in[0] == 0x1f && in[1] == 0x8b) { /* GZIP */
                return COMPRESSION_GZIP;
        } else if(inLen > 1 /*&& (in[0] & 0x10) == Z_DEFLATED*/) {
