    28  static struct sc_context *ctx = NULL;
    29  static struct sc_pkcs15_card *p15card = NULL;
    30  static sc_card_t card = {0};
    31
    32  int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
    33  {
    34      int (* decode_entries[])(struct sc_pkcs15_card *, struct sc_pkcs15_object *,
    35              const u8 **nbuf, size_t *nbufsize) = {
    36          sc_pkcs15_decode_prkdf_entry, sc_pkcs15_decode_pukdf_entry,
    37          sc_pkcs15_decode_skdf_entry, sc_pkcs15_decode_cdf_entry,
    38          sc_pkcs15_decode_dodf_entry, sc_pkcs15_decode_aodf_entry
    39      };
    40      size_t i;
    41
    42      if (!ctx)
    43          sc_establish_context(&ctx, "fuzz");
    44      if (!p15card) {
    45          card.ctx = ctx;
    46          p15card = sc_pkcs15_card_new();
    47          if (p15card) {
    48              p15card->card = &card;
    49          }
    50      }
    51
    52      for (i = 0; i < sizeof decode_entries/sizeof *decode_entries; i++) {
    53          struct sc_pkcs15_object *obj;
    54          const u8 *p = Data;
    55          size_t len = Size;
    56          obj = calloc(1, sizeof *obj);
    57          while (SC_SUCCESS == decode_entries[i](p15card, obj, &p, &len)) {
    58              sc_pkcs15_free_object(obj);
    59              obj = calloc(1, sizeof *obj);
    60          }
    61          sc_pkcs15_free_object(obj);
    62      }
    63
    64      struct sc_pkcs15_pubkey *pubkey = calloc(1, sizeof *pubkey);
    65      sc_pkcs15_decode_pubkey(ctx, pubkey, Data, Size);
    66      sc_pkcs15_free_pubkey(pubkey);
    67
    68      struct sc_pkcs15_tokeninfo *tokeninfo = sc_pkcs15_tokeninfo_new();
    69      sc_pkcs15_parse_tokeninfo(ctx, tokeninfo, Data, Size);
    70      sc_pkcs15_free_tokeninfo(tokeninfo);
    71
    72      sc_pkcs15_parse_unusedspace(Data, Size, p15card);
    73
    74      return 0;
    75  }

