   623  int
   624  sc_pkcs15_encode_odf(struct sc_context *ctx, struct sc_pkcs15_card *p15card,
   625                           unsigned char **buf, size_t *buflen)
   626  {
   627          struct sc_path path;
   628          struct sc_asn1_entry asn1_obj_or_path[] = {
   629                  { "path", SC_ASN1_PATH, SC_ASN1_CONS | SC_ASN1_SEQUENCE, 0, &path, NULL },
   630                  { NULL, 0, 0, 0, NULL, NULL }
   631          };
   632          struct sc_asn1_entry *asn1_paths = NULL;
   633          struct sc_asn1_entry *asn1_odf = NULL;
   634          int df_count = 0, r, c = 0;
   635          const int nr_indexes = sizeof(odf_indexes)/sizeof(odf_indexes[0]);
   636          struct sc_pkcs15_df *df;
   637
   638          df = p15card->df_list;
   639          while (df != NULL) {
   640                  df_count++;
   641                  df = df->next;
   642          };
   643          if (df_count == 0)
   644                  LOG_TEST_RET(ctx, SC_ERROR_OBJECT_NOT_FOUND, "No DF's found.");
   645
   646          asn1_odf = malloc(sizeof(struct sc_asn1_entry) * (df_count + 1));
   647          if (asn1_odf == NULL) {
   648                  r = SC_ERROR_OUT_OF_MEMORY;
   649                  goto err;
   650          }
   651          asn1_paths = malloc(sizeof(struct sc_asn1_entry) * (df_count * 2));
   652          if (asn1_paths == NULL) {
   653                  r = SC_ERROR_OUT_OF_MEMORY;
   654                  goto err;
   655          }
   656          for (df = p15card->df_list; df != NULL; df = df->next) {
   657                  int j, type = -1;
   658
   659                  for (j = 0; j < nr_indexes; j++)
   660                          if (odf_indexes[j] == df->type) {
   661                                  type = j;
   662                                  break;
   663                          }
   664                  if (type == -1) {
   665                          sc_log(ctx, "Unsupported DF type.");
   666                          continue;
   667                  }
   668                  asn1_odf[c] = c_asn1_odf[type];
   669                  sc_format_asn1_entry(asn1_odf + c, asn1_paths + 2*c, NULL, 1);
   670                  sc_copy_asn1_entry(asn1_obj_or_path, asn1_paths + 2*c);
   671                  sc_format_asn1_entry(asn1_paths + 2*c, &df->path, NULL, 1);
   672                  c++;
   673          }
   674          asn1_odf[c].name = NULL;
   675          r = sc_asn1_encode(ctx, asn1_odf, buf, buflen);
   676  err:
   677          if (asn1_paths != NULL)
   678                  free(asn1_paths);
   679          if (asn1_odf != NULL)
   680                  free(asn1_odf);
