   337                  keyinfo_gostparams->gost28147 = (unsigned int)gostr3410_params[2];
   338          }
   339          else if (asn1_pubkey_choice[3].flags & SC_ASN1_PRESENT) {
   340                  obj->type = SC_PKCS15_TYPE_PUBKEY_EC;
   341          }
   342          else {
   343                  obj->type = SC_PKCS15_TYPE_PUBKEY_DSA;
   344          }
   345
   346          if (!p15card->app || !p15card->app->ddo.aid.len) {
   347                  if (!p15card->file_app) {
   348                          r = SC_ERROR_INTERNAL;
   349                          goto err;
   350                  }
   351                  r = sc_pkcs15_make_absolute_path(&p15card->file_app->path, &info->path);
   352                  if (r < 0) {
   353                          goto err;
   354                  }
   355          }
   356          else   {
   357                  info->path.aid = p15card->app->ddo.aid;
   358          }
   359          sc_log(ctx, "PubKey path '%s'", sc_print_path(&info->path));
   360
   361          /* OpenSC 0.11.4 and older encoded "keyReference" as a negative
   362             value. Fixed in 0.11.5 we need to add a hack, so old cards
   363             continue to work. */
   364          if (info->key_reference < -1)
   365                  info->key_reference += 256;
   366
   367          obj->data = info;
   368          info = NULL;
   369
   370          r = sc_pkcs15_decode_pubkey_direct_value(p15card, obj);
   371          if (r < 0) {
   372                  info = obj->data;
   373                  obj->data = NULL;
   374          }
   375          LOG_TEST_GOTO_ERR(ctx, r, "Decode public key direct value failed");
   376
   377  err:
   378          if (r < 0) {
   379                  sc_pkcs15_free_pubkey_info(info);
   380          }
   381
   382          LOG_FUNC_RETURN(ctx, r);
   383  }
